required-complete:
  name: Required complete desktop, source and update results
  needs: [source-syntax, integrated-source-complete, completion-regressions, flite-runtime, portable-sync, trusted-client, managed-update, configured-update-native, integrated-desktop, keyboard-native]
  if: always()
  runs-on: windows-2022
  timeout-minutes: 5
  defaults:
    run:
      shell: pwsh
      working-directory: carr-library
  env:
    CARR_REQUIRED_HEAD: ${{ github.event.pull_request.head.sha || github.sha }}
    CARR_RESULT_SOURCE_SYNTAX: ${{ needs.source-syntax.result }}
    CARR_RESULT_SOURCE_COMPLETE: ${{ needs.integrated-source-complete.result }}
    CARR_RESULT_COMPLETION: ${{ needs.completion-regressions.result }}
    CARR_RESULT_FLITE: ${{ needs.flite-runtime.result }}
    CARR_RESULT_SYNC: ${{ needs.portable-sync.result }}
    CARR_RESULT_TRUSTED_CLIENT: ${{ needs.trusted-client.result }}
    CARR_RESULT_MANAGED_UPDATE: ${{ needs.managed-update.result }}
    CARR_RESULT_CONFIGURED_UPDATE: ${{ needs.configured-update-native.result }}
    CARR_RESULT_DESKTOP: ${{ needs.integrated-desktop.result }}
    CARR_RESULT_KEYBOARD: ${{ needs.keyboard-native.result }}
  steps:
    - name: Check out the exact required source
      timeout-minutes: 2
      uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
      with:
        ref: ${{ github.event.pull_request.head.sha || github.sha }}
        persist-credentials: false
    - name: Require every original lane and configured native update
      timeout-minutes: 1
      run: |
        $ErrorActionPreference = 'Stop'
        $head = (& git rev-parse HEAD).Trim()
        if ($LASTEXITCODE -ne 0 -or $head -cne $env:CARR_REQUIRED_HEAD -or $head -cnotmatch '^[0-9a-f]{40}$') { throw 'The required workflow aggregate has a different HEAD.' }
        $tree = (& git rev-parse 'HEAD^{tree}').Trim()
        if ($LASTEXITCODE -ne 0 -or $tree -cnotmatch '^[0-9a-f]{40}$') { throw 'The required workflow aggregate has no exact tree.' }
        $configuredPath = '.github/workflows/carr-configured-update-native.yml'
        $configuredBlob = (& git rev-parse ('HEAD:' + $configuredPath)).Trim()
        if ($LASTEXITCODE -ne 0 -or $configuredBlob -cne '55bcaba3952137bd588ff64dc0efafc19fc4502b') { throw 'The required configured native workflow differs from its reviewed source.' }
        $results = [ordered]@{
          'source-syntax'=$env:CARR_RESULT_SOURCE_SYNTAX
          'integrated-source-complete'=$env:CARR_RESULT_SOURCE_COMPLETE
          'completion-regressions'=$env:CARR_RESULT_COMPLETION
          'flite-runtime'=$env:CARR_RESULT_FLITE
          'portable-sync'=$env:CARR_RESULT_SYNC
          'trusted-client'=$env:CARR_RESULT_TRUSTED_CLIENT
          'managed-update'=$env:CARR_RESULT_MANAGED_UPDATE
          'configured-update-native'=$env:CARR_RESULT_CONFIGURED_UPDATE
          'integrated-desktop'=$env:CARR_RESULT_DESKTOP
          'keyboard-native'=$env:CARR_RESULT_KEYBOARD
        }
        $failed = @($results.GetEnumerator() | Where-Object { $_.Value -cne 'success' } | ForEach-Object { $_.Key })
        $receipt = [ordered]@{
          schema='carr-required-workflow-results/1'
          status=$(if ($failed.Count -eq 0) { 'PASS' } else { 'FAIL' })
          head=$head; tree=$tree; run_id=[long]$env:GITHUB_RUN_ID; run_attempt=[int]$env:GITHUB_RUN_ATTEMPT
          required_jobs=$results; failed_jobs=$failed
          source_whole_suites=487
          configured_native_workflow=$configuredPath; configured_native_workflow_blob=$configuredBlob
          configured_native_artifact=('configured-update-' + $head + '-' + $env:GITHUB_RUN_ATTEMPT)
          qualification='Required workflow results only; each lane retains its original source, native, hardware and manual acceptance boundaries.'
        }
        New-Item -ItemType Directory -Path 'ci-required-results' -ErrorAction Stop | Out-Null
        $raw = $receipt | ConvertTo-Json -Depth 8
        if ([Text.Encoding]::UTF8.GetByteCount($raw) -gt 16384) { throw 'The required workflow result receipt exceeds its finite bound.' }
        Set-Content -LiteralPath 'ci-required-results/complete-workflow.json' -Value $raw -Encoding utf8
        if ($failed.Count -ne 0) { throw ('Required workflow lanes did not pass: ' + ($failed -join ', ')) }
        Write-Output ('PASS: all ten required workflow results, including original managed update and configured native Apply; head=' + $head)
    - name: Preserve the exact required-workflow result receipt
      if: always()
      timeout-minutes: 1
      uses: actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9
      with:
        name: carr-required-workflow-${{ github.event.pull_request.head.sha || github.sha }}-${{ github.run_attempt }}
        path: carr-library/ci-required-results/complete-workflow.json
        if-no-files-found: error
        retention-days: 7
